function ProfileOrganizationManager({ organizations, setOrganizations, fetcher }: any) {
  const [organizationName, setOrganizationName] = useState(''); const [nickname, setNickname] = useState(''); const [showCreateForm, setShowCreateForm] = useState(false); const [showMemberForm, setShowMemberForm] = useState(false); const [selectedId, setSelectedId] = useState<string | null>(null); const [message, setMessage] = useState('')
  const selected = organizations.find((organization: ApiOrganization) => organization.id === selectedId)
  const request = async (path: string, method: string, body: object) => { const response = await fetcher(path, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (!response.ok) throw Error(); return response.json() }
  const create = async () => { if (!organizationName.trim()) return; try { const item = await request('/organizations', 'POST', { name: organizationName.trim() }); setOrganizations((current: ApiOrganization[]) => [item, ...current]); setOrganizationName(''); setShowCreateForm(false); setSelectedId(item.id); setMessage('Organizácia je vytvorená.') } catch { setMessage('Organizáciu sa nepodarilo vytvoriť.') } }
  const addMember = async () => { if (!selected || !nickname.trim()) return; try { const item = await request(`/organizations/${selected.id}/members`, 'POST', { nickname: nickname.trim() }); setOrganizations((current: ApiOrganization[]) => current.map((organization) => organization.id === item.id ? item : organization)); setNickname(''); setMessage('Člen je pridaný.') } catch { setMessage('Člena sa nepodarilo pridať. Pridávať môže iba vlastník organizácie.') } }
  if (selected) return <Modal visible transparent animationType="slide" onRequestClose={() => { setSelectedId(null); setMessage('') }}><View style={styles.modalOverlay}><View style={styles.modalSheet}><View style={teamStyles.info}><Text style={styles.modalTitle}>{selected.name}</Text><Text style={teamStyles.muted}>{selected.members.length} členovia</Text></View><Text style={teamStyles.sectionTitle}>ČLENOVIA</Text><ScrollView style={{ maxHeight: 260 }} contentContainerStyle={teamStyles.section}>{selected.members.map((member: any) => <View key={member.id} style={teamStyles.member}><Text style={teamStyles.title}>@{member.nickname}</Text><Text style={teamStyles.muted}>{member.role}</Text></View>)}</ScrollView><Pressable style={teamStyles.button} onPress={() => setShowMemberForm(true)}><Text style={teamStyles.buttonText}>+ Pridať člena</Text></Pressable><Pressable onPress={() => { setSelectedId(null); setMessage('') }}><Text style={styles.cancelText}>Zavrieť</Text></Pressable>{message ? <Text style={styles.error}>{message}</Text> : null}<Modal visible={showMemberForm} transparent animationType="fade" onRequestClose={() => setShowMemberForm(false)}><View style={styles.modalOverlay}><View style={styles.modalSheet}><Text style={styles.modalTitle}>Pridať člena</Text><TextInput value={nickname} onChangeText={setNickname} placeholder="Nick nového člena" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="none" /><View style={styles.modalActions}><Pressable onPress={() => setShowMemberForm(false)}><Text style={styles.cancelText}>Zrušiť</Text></Pressable><Pressable style={styles.saveDateButton} onPress={() => { void addMember(); setShowMemberForm(false) }}><Text style={styles.saveDateText}>Pridať</Text></Pressable></View></View></View></Modal></View></View></Modal>
  return <View style={teamStyles.section}><Text style={teamStyles.sectionTitle}>ORGANIZÁCIE</Text>{organizations.map((organization: ApiOrganization) => <Pressable key={organization.id} style={teamStyles.card} onPress={() => setSelectedId(organization.id)}><View style={teamStyles.info}><Text style={teamStyles.title}>{organization.name}</Text><Text style={teamStyles.muted}>{organization.members.length} členovia</Text></View><Text style={teamStyles.buttonText}>›</Text></Pressable>)}<Pressable style={teamStyles.button} onPress={() => setShowCreateForm(true)}><Text style={teamStyles.buttonText}>+ Vytvoriť organizáciu</Text></Pressable>{message ? <Text style={styles.error}>{message}</Text> : null}<Modal visible={showCreateForm} transparent animationType="fade" onRequestClose={() => setShowCreateForm(false)}><View style={styles.modalOverlay}><View style={styles.modalSheet}><Text style={styles.modalTitle}>Vytvoriť organizáciu</Text><TextInput value={organizationName} onChangeText={setOrganizationName} placeholder="Názov organizácie" placeholderTextColor="#9aa0a8" style={styles.input} /><View style={styles.modalActions}><Pressable onPress={() => setShowCreateForm(false)}><Text style={styles.cancelText}>Zrušiť</Text></Pressable><Pressable style={styles.saveDateButton} onPress={() => void create()}><Text style={styles.saveDateText}>Vytvoriť</Text></Pressable></View></View></View></Modal></View>
}

function DatabaseTeamsProfile(props: any) {
  const { authenticatedFetch } = useAuth()
  const [organizations, setOrganizations] = useState<ApiOrganization[]>([])
  useEffect(() => { void authenticatedFetch('/organizations/mine').then(response => response.ok ? response.json() : []).then(setOrganizations).catch(() => setOrganizations([])) }, [])
  return <><TeamsProfileContent {...props} /><Text style={teamStyles.sectionTitle}>MOJE ORGANIZÁCIE</Text><ProfileOrganizationManager organizations={organizations} setOrganizations={setOrganizations} fetcher={authenticatedFetch} /></>
}

function DatabaseTeamDetail({ team, onBack, onAdd }: { team: ApiTeam; onBack: () => void; onAdd: (id: string, nickname: string) => Promise<void> }) {
  const [adding, setAdding] = useState(false); const [nickname, setNickname] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  const add = async () => { if (!nickname.trim()) return; setBusy(true); setError(''); try { await onAdd(team.id, nickname); setNickname(''); setAdding(false) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Hraca sa nepodarilo pridat.') } finally { setBusy(false) } }
  return <><Pressable onPress={onBack}><Text style={teamStyles.back}>← Spat na profil</Text></Pressable><View style={[teamStyles.card, teamStyles.hero]}><Text style={teamStyles.title}>{team.name}</Text><Text style={teamStyles.muted}>{team.members.length} clenovia</Text></View><Text style={teamStyles.sectionTitle}>HRACI TIMU</Text>{team.members.map(member => <View style={teamStyles.member} key={member.id}><View style={teamStyles.memberAvatar}><Text style={teamStyles.memberAvatarText}>{member.nickname.slice(0, 1).toUpperCase()}</Text></View><Text style={teamStyles.title}>@{member.nickname}</Text></View>)}{adding ? <View style={teamStyles.form}><Text style={teamStyles.title}>Pridat hraca cez nick</Text><Text style={teamStyles.muted}>Zadaj presny jedinecny nick hraca.</Text><TextInput value={nickname} onChangeText={setNickname} placeholder="nick_hraca" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="none" autoCorrect={false} /><View style={teamStyles.actions}><Pressable onPress={() => setAdding(false)}><Text style={teamStyles.cancel}>Zrusit</Text></Pressable><Pressable style={teamStyles.primary} onPress={() => void add()} disabled={busy}><Text style={teamStyles.primaryText}>Pridat</Text></Pressable></View>{error ? <Text style={styles.error}>{error}</Text> : null}</View> : <Pressable style={teamStyles.button} onPress={() => setAdding(true)}><Text style={teamStyles.buttonText}>+ Pridat hraca cez nick</Text></Pressable>}</>
}

function TeamsProfile(_: any) { return null }
function TeamDetail(_: any) { return null }

function MainApp({ name, onSignOut }: { name: string; onSignOut: () => Promise<void> }) {
  const [tab, setTab] = useState<MainTab>('home'); const [teams, setTeams] = useState<Team[]>([]); const [selectedId, setSelectedId] = useState<string | null>(null)
  useEffect(() => { void getStoredValue(TEAM_STORAGE_KEY).then(value => { if (!value) return; try { setTeams(JSON.parse(value) as Team[]) } catch { /* corrupt local state */ } }) }, [])
  const save = (next: Team[]) => { setTeams(next); void setStoredValue(TEAM_STORAGE_KEY, JSON.stringify(next)) }
  const create = (teamName: string) => { const team: Team = { id: `${Date.now()}-${Math.random()}`, name: teamName.trim(), color: teamColors[teams.length % teamColors.length], members: [{ id: 'captain', nickname: `${name} (kapitán)` }] }; save([...teams, team]); setSelectedId(team.id) }
  const addPlayer = (teamId: string, nickname: string) => save(teams.map(t => t.id === teamId ? { ...t, members: [...t.members, { id: `${Date.now()}-${Math.random()}`, nickname: nickname.trim() }] } : t))
  const selected = teams.find(t => t.id === selectedId)
  return <View style={mainStyles.mainApp}><View style={mainStyles.mainHeader}><View><Text style={mainStyles.headerBrand}>3×3 <Text style={styles.accent}>SPORT</Text></Text><Text style={mainStyles.headerTitle}>{selected?.name ?? (tab === 'profile' ? 'Profil' : tab === 'home' ? 'Domov' : tab === 'events' ? 'Eventy' : 'Ranking')}</Text></View></View><ScrollView contentContainerStyle={mainStyles.mainContent}>{selected ? <TeamDetail team={selected} onBack={() => setSelectedId(null)} onAdd={addPlayer} /> : tab === 'profile' ? <TeamsProfile name={name} teams={teams} onCreate={create} onOpen={setSelectedId} onSignOut={onSignOut} /> : tab === 'home' ? <HomeTab name={name} /> : <PlaceholderTab icon="•" title={tab === 'events' ? 'Eventy' : 'Ranking'} description="Pripravujeme pre teba ďalší obsah." />}</ScrollView>{!selected && <BottomNavigation active={tab} onChange={setTab} />}</View>
}

